return [
  { json: { query: "lancamento motos 2026 Brasil" } },
  { json: { query: "recalls motos recentes Brasil" } },
  { json: { query: "Moto GP" } },
  { json: { query: "Honda motos mercado 2026" } },
  { json: { query: "mercado de duas rodas noticias" } },
  { json: { query: "TT ilha de man" } }
];

const xmlString = $input.first().json.data;
const now = new Date();
const noticias = [];

// Regex para capturar cada bloco <item>
const itemRegex = /<item>([\s\S]*?)<\/item>/g;
let match;

while ((match = itemRegex.exec(xmlString)) !== null) {
  const itemContent = match[1];

  // Função auxiliar para extrair tags XML (ignora CDATA automaticamente)
  const extractTag = (tag) => {
    const regex = new RegExp(`<${tag}[^>]*>(?:<!\\[CDATA\\[([\\s\\S]*?)\\]\\]>)?([\\s\\S]*?)<\\/${tag}>`, 'i');
    const tagMatch = itemContent.match(regex);
    if (!tagMatch) return '';
    return (tagMatch[1] || tagMatch[2] || '').trim();
  };

  const title = extractTag('title');
  const link = extractTag('link');
  const pubDateStr = extractTag('pubDate');

  let pubDate = new Date(pubDateStr);
  let daysAgo = 999;

  if (!isNaN(pubDate)) {
    // Calcula a diferença em dias (1000ms * 60s * 60m * 24h)
    daysAgo = (now - pubDate) / (1000 * 60 * 60 * 24);
  }

  // Filtra APENAS notícias dos últimos 30 dias
  if (daysAgo <= 30) {
    noticias.push({
      titulo: title,
      link: link,
      data_publicacao: pubDateStr
    });
  }
}

// Retorna os dados mastigados e organizados
return [{
  json: {
    noticias_motogp: noticias,
    total_encontrado: noticias.length
  }
}];

const dados = $input.first().json;
const tendencias = [];

// Verifica se existe o array de buscas em alta
if (dados.trending_searches) {
    dados.trending_searches.forEach(item => {
        tendencias.push({
            termo_buscado: item.query,
            volume_busca: item.search_volume,
            crescimento: `${item.increase_percentage}%`
        });
    });
}

// Retorna os dados organizados na mesma estrutura do Motorsport
return [{
    json: {
        tendencias_brasil: tendencias,
        total_encontrado: tendencias.length
    }
}];

const items = $input.all();
let newsData = [];
let linksVistos = new Set(); // Para evitar notícias duplicadas

items.forEach(item => {
    // Verifica se o item possui a estrutura de resultados do Google News
    if (item.json && item.json.news_results) {

        // Pega os 5 primeiros resultados de cada uma das 6 queries para não sobrecarregar a IA
        let resultados = item.json.news_results.slice(0, 5);

        resultados.forEach(n => {
            // Checa se a notícia já foi adicionada (evita repetições de pautas iguais)
            if (!linksVistos.has(n.link)) {
                linksVistos.add(n.link);

                newsData.push({
                    titulo: n.title,
                    fonte: n.source?.name || 'Desconhecido',
                    link: n.link,
                    data_publicacao: n.date
                });
            }
        });
    }
});

// Ordena as notícias da mais recente para a mais antiga (baseado na string de data do Google)
newsData.sort((a, b) => new Date(b.data_publicacao) - new Date(a.data_publicacao));

// Retorna o payload estruturado para se juntar ao Merge final
return [{
    json: {
        manchetes_google_news: newsData,
        total_encontrado: newsData.length
    }
}];

